  { x: 1150, y: 880, w: 60, h: 44, kind: 'crate' },
];
export const SOLIDS = [...WALLS, ...OBSTACLES];
// One brazier per room, at the room centre.
export const BRAZIERS = [
  { x: 432, y: 318 },
  { x: 1216, y: 318 },
  { x: 432, y: 762 },
  { x: 1216, y: 762 },
